import { defineConfig, lazyPlugins } from 'vite-plus'
import react from '@vitejs/plugin-react'
import { cloudflare } from '@cloudflare/vite-plugin'
import { sliderChunks } from './tools/sliderChunks'

// Generated by the look fitting pipeline; never hand-edited, so neither linted nor formatted.
const GENERATED = [
  'src/model/catalog.ts',
  'src/model/catalogSliders.ts',
  'src/model/toolTables.ts',
  'src/model/stripCatalog.ts',
]

export default defineConfig({
  lint: {
    jsPlugins: [{ name: 'vite-plus', specifier: 'vite-plus/oxlint-plugin' }],
    rules: { 'vite-plus/prefer-vite-plus-imports': 'error' },
    options: { typeAware: true, typeCheck: true },
    // tools/ holds bun scripts outside the app's tsconfig (node:fs, import.meta.main).
    ignorePatterns: ['tools/**', '.cloudflare/**', ...GENERATED],
  },
  fmt: { semi: false, singleQuote: true, printWidth: 120, ignorePatterns: GENERATED },
  // The codebase predates the formatter; `vp check` skips formatting until it is adopted.
  check: { fmt: false },
  plugins: lazyPlugins(() => [react(), sliderChunks(), cloudflare()]),
  server: { port: 5199, strictPort: true },
  // The HEIC decoder is already one ES module; pre-bundling it on first use reloaded the page mid-import.
  // ExifReader is pre-bundled up front: found on first use, the dev server rebundled it and reloaded mid-import.
  // libraw-wasm finds its worker next to its own file, which pre-bundling breaks.
  optimizeDeps: { exclude: ['libheif-js', 'libraw-wasm'], include: ['exifreader'] },
  build: {
    // The generated look data is large by nature: the catalog about 1.8 MB (1.2 MB gzipped, on the
    // startup path), the slider tables split into lazy chunks per look (74 tables, 8.3 MB total), the HEIC
    // decoder 2 MB (only with a HEIC file) and the RAW decoder's wasm (only with a RAW file). Storing the
    // tables as binary instead of base64 was measured at 12% less gzipped, not worth a second format.
    chunkSizeWarningLimit: 6400,
    rolldownOptions: {
      // The fitted look data changes rarely and is large; keep it in its own
      // chunk so it downloads in parallel and caches apart from app code.
      output: { codeSplitting: { groups: [{ name: 'looks', test: /src\/model\/catalog\.ts$/ }] } },
    },
  },
  test: { environment: 'node', include: ['src/**/*.test.ts'] },
})
